                    {
                        set_preview_scale(cmd - ID_TRAY_SCALE_BASE)
                    }
                    ID_TRAY_THEME_LIGHT => set_theme(TextTheme::Light),
                    ID_TRAY_THEME_DARK => set_theme(TextTheme::Dark),
                    // The `theme` folder's items, by the position the submenu gave
