                    cmd if (ID_TRAY_LIBREOFFICE_IDLE_BASE
                        ..ID_TRAY_LIBREOFFICE_IDLE_BASE + ENGINE_IDLE_CHOICES.len() as u16)
                        .contains(&cmd) =>
                    {
                        set_libreoffice_idle(cmd - ID_TRAY_LIBREOFFICE_IDLE_BASE)
