                    cmd if (ID_TRAY_AUDIO_SCALE_BASE
                        ..ID_TRAY_AUDIO_SCALE_BASE + AUDIO_SCALE_CHOICES.len() as u16)
                        .contains(&cmd) =>
                    {
                        set_audio_scale(cmd - ID_TRAY_AUDIO_SCALE_BASE)
